}

function suiteHead(absPath) {
  let head = "";
  try {
    const fd = fs.openSync(absPath, "r");
    try {
      const buf = Buffer.alloc(8192);
      const n = fs.readSync(fd, buf, 0, buf.length, 0);
      head = buf.toString("utf8", 0, n);
    } finally {
      fs.closeSync(fd);
    }
  } catch {
    return "";
  }
  return head.split("\n").slice(0, SERIAL_HEAD_LINES).join("\n");
}

export function isSerialSuite(absPath) {
  return SERIAL_MARK_RE.test(suiteHead(absPath));
}

